-- Seed gerado por assets/gerador-avaliacao-discursiva (não editar à mão; fora do Git).
-- Rodar depois de database/2026-10-01-respostas-discursivas.sql. Idempotente.
-- A avaliação nasce BLOQUEADA (ativo = false): o professor libera no índice de atividades.
do $$
declare
  v_aula bigint;
  v_atividade bigint;
begin
  select a.id into v_aula from public.aulas a join public.materia m on m.id = a.materia_id
    where m.descricao = 'Fundamentos de UI / UX' and a.numero = 17
    order by a.id limit 1;
  if v_aula is null then
    raise exception 'Aula 17 da matéria não encontrada';
  end if;

  insert into public.atividade (nome_atividade, status, aula_id, descricao, pagina,
      total_itens, ativo)
    values ('Atividade Prática — Aula 17', 'PENDENTE', v_aula, 'Atividade — Atividade Prática — Aula 17 (20 questões discursivas)',
      '/MATERIAIS/TECNICO-INFORMATICA-INTERNET/FUNDAMENTOS-DE-UI-UX/ATIVIDADES/ATIVIDADE-PRATICA-AULA-17.html', 20, false)
    on conflict (pagina) do update set aula_id = excluded.aula_id,
      descricao = excluded.descricao, total_itens = excluded.total_itens
    returning id into v_atividade;

  delete from public.topico_discursivo where atividade_id = v_atividade;
  insert into public.topico_discursivo (atividade_id, item, topico, enunciado, pontos,
      resposta_esperada, criterios) values
      (v_atividade, 1, 1, 'Explique o que significa separar o que entra e o que não entra no projeto.', 0.2, 'Separar o que entra no projeto (funções aprovadas e essenciais) do que não entra (funções secundárias ou pedidos fora da dor central), criando fronteiras claras antes de desenhar telas.', 'Nota cheia: define a separação entre o que entra e o que não entra, com fronteiras claras. Metade: cita a separação, mas sem explicar o sentido ou sem as fronteiras. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 1, 2, 'Relacione a priorização dos recursos essenciais com a dor central do usuário.', 0.4, 'Priorizar os recursos essenciais é manter o foco nas funções que resolvem a dor central do usuário, deixando de lado o que não contribui para isso.', 'Nota cheia: relaciona a priorização dos essenciais com a dor central do usuário. Metade: menciona a priorização ou a dor do usuário, mas sem fazer a relação. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 1, 3, 'Explique como funções secundárias podem afetar o cronograma de entrega.', 0.4, 'Funções secundárias consomem tempo de desenho, de desenvolvimento e de testes, e por isso atrasam o cronograma de entrega.', 'Nota cheia: explica que funções secundárias consomem tempo e atrasam a entrega. Metade: diz que atrasam, sem explicar o motivo. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 2, 1, 'Diga o que é prototipar, com as suas palavras.', 0.2, 'Prototipar é dar forma palpável e testável a uma ideia abstrata, criando um modelo experimental para validar se ela resolve o problema real de quem usa.', 'Nota cheia: explica prototipar como criar um modelo para testar uma ideia antes da produção, com as palavras do aluno. Metade: cita testar ou modelo, sem explicar o propósito. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 2, 2, 'Explique por que o objetivo não é deixar o protótipo bonito ou finalizado.', 0.4, 'O objetivo não é deixar o protótipo bonito ou finalizado, porque o foco é aprender rápido com falhas e ajustar a estrutura; deixar bonito gasta tempo sem validar nada.', 'Nota cheia: explica que o foco é aprender com falhas e ajustar a estrutura, e que o acabamento não é o objetivo. Metade: diz que não é para ser bonito, sem explicar o aprendizado. Zero: em branco, errado ou afirma que o protótipo deve ser finalizado.'),
      (v_atividade, 2, 3, 'Explique como o aprendizado rápido com falhas reduz o desperdício de tempo.', 0.4, 'Ao descobrir as falhas cedo, a equipe corrige a estrutura em minutos, sem reescrever código nem refazer o trabalho já pronto, e assim evita gastar tempo com a solução errada.', 'Nota cheia: relaciona achar falhas cedo com a correção rápida e a economia de tempo ou retrabalho. Metade: diz que é mais rápido, sem relacionar com as falhas. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 3, 1, 'Descreva o custo de corrigir um erro no papel e esboçando.', 0.2, 'No papel e no esboço o custo é quase zero: basta apagar com borracha ou desenhar outra folha em minutos.', 'Nota cheia: descreve custo quase zero e a correção com borracha ou nova folha em minutos. Metade: diz que é barato, sem citar a forma de correção. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 3, 2, 'Descreva o custo de corrigir o mesmo erro no design digital.', 0.4, 'No design digital o custo é médio, porque é preciso remodelar componentes e vetores nas ferramentas digitais, o que leva mais tempo do que no papel.', 'Nota cheia: descreve custo médio e o retrabalho de remodelar componentes ou vetores. Metade: diz que custa mais que o papel, sem detalhar. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 3, 3, 'Descreva o custo de corrigir o erro com o código já em produção e explique a diferença em relação às outras etapas.', 0.4, 'Com o código já em produção o custo é altíssimo, pois é preciso reprogramar telas, testar o banco de dados e redistribuir aos usuários. A diferença é que o custo cresce a cada etapa avançada do projeto.', 'Nota cheia: descreve custo altíssimo (reprogramar telas, testar banco, redistribuir) e explica que o custo cresce em relação às etapas anteriores. Metade: descreve o custo alto, sem comparar com as outras etapas. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 4, 1, 'Diga qual é a definição de storyboard, segundo a aula.', 0.2, 'Storyboard é a história visual da experiência do usuário no seu ambiente cotidiano, contada em quadros, como uma sequência de quadrinhos.', 'Nota cheia: define storyboard como a história visual da experiência do usuário no ambiente cotidiano. Metade: diz que é uma história ou uma sequência de quadros, sem citar a experiência do usuário. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 4, 2, 'Explique o que o storyboard mostra além das telas, citando quem é o usuário e onde ele está.', 0.4, 'Além das telas, o storyboard mostra quem é o usuário (o personagem), onde ele está (o cenário), qual é a necessidade urgente dele e como o sistema o ajuda a resolver o problema.', 'Nota cheia: cita quem é o usuário e onde ele está, além de falar da necessidade ou de como o sistema ajuda. Metade: cita só um dos dois (quem ou onde). Zero: em branco, errado ou fala só de telas e botões.'),
      (v_atividade, 4, 3, 'Explique por que o storyboard coloca a necessidade do usuário no centro do problema.', 0.4, 'O storyboard coloca a necessidade do usuário no centro porque mostra o problema real do mundo dele, e não apenas os botões isolados; assim a interface é pensada para resolver uma situação humana.', 'Nota cheia: explica que a necessidade do usuário é o centro, em contraste com desenhar só botões ou telas isoladas. Metade: diz que o usuário é o centro, sem o contraste. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 5, 1, 'Descreva o elemento Personagem e as informações que ele precisa conter.', 0.2, 'O Personagem é o usuário principal, com suas motivações, limitações de tempo e necessidades claras.', 'Nota cheia: descreve o personagem como o usuário principal com motivações, limitações (ex.: tempo) e necessidades. Metade: diz que é o usuário, sem as informações que ele deve conter. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 5, 2, 'Descreva o elemento Cenário e dê dois exemplos de condições do ambiente que o compõem.', 0.4, 'O Cenário é o ambiente físico onde a ação ocorre. Exemplos: iluminação forte, barulho, pressa ou chuva.', 'Nota cheia: descreve o cenário como ambiente físico e dá dois exemplos de condições (ex.: iluminação, barulho, pressa, chuva). Metade: descreve o cenário, mas dá só um exemplo ou nenhum. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 5, 3, 'Explique a relação entre o Conflito e o Desfecho na narrativa do storyboard.', 0.4, 'O Conflito é o obstáculo que o usuário enfrenta; o Desfecho é a resolução positiva gerada pela interação eficaz com a interface. O desfecho só existe se a interface superar o conflito.', 'Nota cheia: explica que o conflito é o obstáculo e o desfecho é a resolução pela interface, e que o desfecho depende de superar o conflito. Metade: define os dois, sem relacioná-los. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 6, 1, 'Descreva o quadro que mostra a dor do usuário, antes de abrir o protótipo.', 0.2, 'O primeiro quadro mostra a dor surgindo: o usuário precisa agendar uma consulta antes de sair para o trabalho ou a escola.', 'Nota cheia: descreve o quadro da dor, com o usuário precisando agendar a consulta antes de sair. Metade: descreve o quadro, sem a urgência ou sem a dor. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 6, 2, 'Descreva o quadro que mostra a ação direta do usuário na tela.', 0.4, 'O quadro da ação direta mostra o usuário abrindo o protótipo (no celular), selecionando a data desejada e clicando no botão de confirmação.', 'Nota cheia: descreve a ação do usuário na tela, com a escolha da data e o clique em confirmar. Metade: descreve uma ação na tela, sem o passo completo. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 6, 3, 'Descreva o quadro do problema resolvido e explique por que ele fecha a narrativa.', 0.4, 'O quadro do problema resolvido mostra o usuário recebendo o aviso imediato na tela e seguindo o dia sem estresse. Ele fecha a narrativa porque mostra o resultado da história, com a necessidade atendida.', 'Nota cheia: descreve o aviso de confirmação e o alívio do usuário, e explica que fecha a narrativa por mostrar a necessidade resolvida. Metade: descreve o quadro final, sem explicar por que fecha a narrativa. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 7, 1, 'Indique qual deve ser o primeiro passo da narrativa e por quê.', 0.2, 'O primeiro passo é identificar o contexto e o problema enfrentado pelo usuário, porque sem entender a situação não há motivo para desenhar a interface.', 'Nota cheia: indica identificar o contexto e o problema do usuário como primeiro passo, com o porquê. Metade: indica o primeiro passo, sem justificar. Zero: em branco, errado (ex.: começar pelo desfecho) ou fora do tema.'),
      (v_atividade, 7, 2, 'Indique qual deve ser o último passo da narrativa e o que ele mostra.', 0.4, 'O último passo é mostrar o desfecho satisfatório, com a tarefa concluída.', 'Nota cheia: indica o desfecho satisfatório com a tarefa concluída como último passo. Metade: indica o desfecho, sem dizer que mostra a tarefa concluída. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 7, 3, 'Explique por que a interação direta do usuário vem antes do desfecho.', 0.4, 'A interação direta do usuário com as telas vem antes do desfecho porque o desfecho é consequência da ação dele; não há resolução antes de a pessoa agir.', 'Nota cheia: explica que o desfecho depende da ação do usuário e por isso vem depois. Metade: diz a ordem, sem o motivo. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 8, 1, 'Diga do que são feitos os protótipos de papel.', 0.2, 'Protótipos de papel são feitos com folhas avulsas, cartolinas, tesoura e lápis, formando maquetes visuais das telas.', 'Nota cheia: cita materiais de papel (folhas, cartolinas, tesoura, lápis) e que são maquetes das telas. Metade: diz que são feitos de papel, sem os detalhes. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 8, 2, 'Explique quais aspectos o protótipo de papel prioriza, como hierarquia e posicionamento.', 0.4, 'Na fase inicial, o protótipo de papel prioriza a hierarquia das informações, o posicionamento dos botões e o fluxo entre as telas.', 'Nota cheia: cita hierarquia e posicionamento (e, se possível, o fluxo entre telas). Metade: cita só um dos aspectos, ou um aspecto que não está na aula. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 8, 3, 'Explique por que fontes sofisticadas e cores complexas não devem ser o foco nessa fase.', 0.4, 'Fontes sofisticadas, ilustrações finais e cores complexas distraem a equipe e o testador, sem ajudar a validar a estrutura, que é o foco nessa fase.', 'Nota cheia: explica que esses elementos distraem e não ajudam a validar a estrutura nesta fase. Metade: diz que não devem ser o foco, sem explicar por quê. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 9, 1, 'Explique a vantagem de custo do protótipo de papel.', 0.2, 'A vantagem de custo é que o protótipo de papel exige só papel comum, lápis e régua, disponíveis em qualquer sala de aula ou escritório, sem gastar com licenças de software.', 'Nota cheia: explica o custo quase zero com materiais simples e disponíveis. Metade: diz que é barato, sem explicar os materiais. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 9, 2, 'Explique o que é a correção veloz no papel e dê um exemplo de uso durante um teste.', 0.4, 'A correção veloz é poder rasurar na hora ou desenhar uma nova tela em dois minutos. Exemplo: se uma opção confunde o testador, a equipe rasura ou desenha outra tela na hora, durante o teste.', 'Nota cheia: explica a correção veloz (rasurar ou desenhar nova tela em minutos) e dá um exemplo durante o teste. Metade: explica a correção, sem exemplo de teste. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 9, 3, 'Explique o que significa o desapego total e como ele favorece críticas sinceras.', 0.4, 'O desapego total significa que ninguém tem receio de criticar ou descartar um desenho simples feito em uma tira de papel; por isso as críticas tendem a ser mais sinceras.', 'Nota cheia: explica o desapego (desenho simples, sem receio de criticar ou descartar) e a relação com críticas sinceras. Metade: explica o desapego, sem relacionar com a sinceridade. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 10, 1, 'Descreva duas formas de alterar o protótipo durante a sessão, citadas na aula.', 0.2, 'Duas formas citadas na aula: alterar com borracha (rasurando) e colocar novos recortes ou notas adesivas durante a sessão.', 'Nota cheia: descreve duas formas (ex.: borracha e novos recortes ou notas adesivas). Metade: descreve uma forma. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 10, 2, 'Explique por que essa alteração imediata é uma vantagem da baixa fidelidade.', 0.4, 'A alteração imediata é uma vantagem porque a equipe corrige o problema na hora e o teste continua com a versão ajustada, sem esperar uma nova versão digital.', 'Nota cheia: explica que a alteração é imediata e que o teste continua com a versão corrigida, sem espera. Metade: diz que é rápido, sem relacionar com o teste. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 10, 3, 'Explique por que o protótipo de papel não substitui a escrita do código final.', 0.4, 'O protótipo de papel serve para testar fluxos e estrutura, e não entrega funcionalidade real; o código final ainda precisa ser escrito pelos programadores.', 'Nota cheia: explica que o papel testa o fluxo e não entrega o código ou a funcionalidade real. Metade: diz que não substitui o código, sem o motivo. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 11, 1, 'Explique a função das folhas e molduras no kit.', 0.2, 'As folhas e molduras são folhas A4 recortadas na proporção do smartphone ou do monitor, que servem de chassi (base) do protótipo.', 'Nota cheia: explica que as folhas e molduras são a base (chassi) recortada na proporção da tela. Metade: diz que servem de base, sem a proporção. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 11, 2, 'Explique para que servem as notas adesivas e dê um exemplo de elemento que elas simulam.', 0.4, 'As notas adesivas simulam elementos que surgem na tela, como caixas de diálogo, alertas, teclados virtuais e menus deslizantes. Exemplo: um alerta de sucesso ou um teclado virtual.', 'Nota cheia: explica a função das notas adesivas e dá um exemplo de elemento simulado. Metade: explica a função, sem exemplo. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 11, 3, 'Explique como as tiras e cartões imitam a rolagem de feeds e listas.', 0.4, 'As tiras e cartões deslizam por trás da moldura e imitam a rolagem (scroll) de feeds e listas, mostrando novos itens conforme são puxados.', 'Nota cheia: explica que as tiras deslizam por trás da moldura para imitar a rolagem de feeds e listas. Metade: diz que imitam a rolagem, sem o mecanismo. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 12, 1, 'Explique como representar um menu expansível no papel.', 0.2, 'Um menu expansível é representado por uma tira de papel dobrada, que é aberta quando o usuário clica no botão.', 'Nota cheia: descreve a tira dobrada que se abre ao clique no botão. Metade: descreve a abertura do menu, sem o recurso de papel. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 12, 2, 'Explique como representar uma mensagem de alerta do tipo modal.', 0.4, 'Uma mensagem de alerta do tipo modal é representada por uma nota adesiva colada no centro, cobrindo a tela atual.', 'Nota cheia: descreve a nota adesiva central cobrindo a tela atual. Metade: descreve uma nota adesiva, sem a posição central ou a cobertura da tela. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 12, 3, 'Explique como representar um campo em que o usuário digita um texto.', 0.4, 'Um campo de texto é representado por um pequeno pedaço de papel com texto manuscrito, colocado quando o usuário "digita".', 'Nota cheia: descreve o pequeno papel com texto manuscrito trocado quando o usuário digita. Metade: diz que se usa um papel com texto, sem o momento da digitação. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 13, 1, 'Explique o que é a técnica do homem-computador e por que também é chamada de Mágico de Oz.', 0.2, 'A técnica do homem-computador é uma encenação teatral em que um integrante reage aos toques do usuário no papel, simulando a interface. Recebe o nome de Mágico de Oz porque a interface parece responder sozinha, quando na verdade alguém a move por trás.', 'Nota cheia: explica a técnica como simulação em que um membro da equipe reage aos toques, e explica o apelido de Mágico de Oz. Metade: explica a técnica, sem o apelido. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 13, 2, 'Descreva o que o membro da equipe faz a cada toque do usuário na folha de papel.', 0.4, 'A cada toque do usuário na folha, o membro da equipe move, substitui ou cola manualmente o elemento seguinte que a tela apresentaria.', 'Nota cheia: descreve mover, substituir ou colar o próximo elemento a cada toque. Metade: diz que reage ao toque, sem a ação concreta. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 13, 3, 'Explique por que o homem-computador nunca deve falar nem ensinar onde clicar.', 0.4, 'Ele nunca fala nem ensina onde clicar porque deve apenas reagir ao toque; se orientar, o teste avalia a orientação dada e deixa de avaliar a intuição do usuário.', 'Nota cheia: diz que não fala nem ensina, e explica que apenas reage ao toque para o teste medir a intuição. Metade: diz que não fala, sem o motivo. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 14, 1, 'Descreva o papel do facilitador.', 0.2, 'O facilitador apresenta o objetivo da tarefa, acolhe o testador e pede que ele pense em voz alta.', 'Nota cheia: descreve apresentar o objetivo, acolher o testador e pedir que pense em voz alta. Metade: descreve uma ou duas dessas ações. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 14, 2, 'Descreva o papel do computador na sessão.', 0.4, 'O computador troca as folhas, os recortes e os menus em silêncio absoluto, conforme os toques do usuário ocorrem.', 'Nota cheia: descreve trocar folhas, recortes e menus em silêncio, conforme os toques. Metade: diz que troca as telas, sem o silêncio. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 14, 3, 'Descreva o papel do anotador e explique por que ele é importante para a equipe.', 0.4, 'O anotador registra onde o usuário hesitou, o que ele procurou na tela e onde ficou confuso. É importante porque guarda os registros que orientam os ajustes da equipe.', 'Nota cheia: descreve o registro de hesitações, buscas e confusões, e explica a importância para os ajustes. Metade: descreve o registro, sem a importância. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 15, 1, 'Explique o que a instrução exata de onde clicar avalia, segundo a aula.', 0.2, 'A instrução exata de onde clicar avalia se a pessoa sabe seguir ordens, e não se a interface é intuitiva.', 'Nota cheia: diz que avalia a obediência a ordens e não a intuitividade. Metade: diz que não avalia a intuição, sem o contraste. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 15, 2, 'Explique o que uma formulação com cenário e objetivo aberto permite observar.', 0.4, 'Com cenário e objetivo aberto, a navegação fica por conta do usuário, e a equipe observa por onde ele procura, hesita e chega ao resultado.', 'Nota cheia: explica que o cenário e o objetivo aberto deixam a navegação com o usuário, e que a equipe observa seu caminho. Metade: diz que o usuário navega sozinho, sem o que se observa. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 15, 3, 'Escreva uma tarefa de teste para marcar uma consulta, com cenário e objetivo aberto, sem indicar onde clicar.', 0.4, 'Exemplo de tarefa: "Você precisa marcar uma consulta odontológica para quinta-feira às 14h. Mostre como faria isso usando esta tela." A tarefa não indica onde clicar.', 'Nota cheia: escreve uma tarefa com cenário (marcar consulta) e objetivo aberto, sem indicar onde clicar. Metade: escreve tarefa com cenário, mas indica o botão ou o caminho. Zero: em branco, errado (ex.: dá instrução exata de cliques) ou fora do tema.'),
      (v_atividade, 16, 1, 'Descreva as ações feitas com lápis e borracha após o relato do testador.', 0.2, 'Após o relato, a equipe apaga o texto dúbio com borracha, redesenha a posição do botão (ex.: no padrão F de leitura) ou cola uma nota adesiva com um novo atalho.', 'Nota cheia: descreve pelo menos uma ação a lápis e borracha (apagar, redesenhar ou colar nota) após o relato. Metade: descreve uma ação genérica de corrigir, sem lápis, borracha ou nota. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 16, 2, 'Explique por que a equipe não precisa agendar uma reunião formal de dias para isso.', 0.4, 'A correção é feita na hora, com lápis e borracha, e a equipe não precisa de reunião formal porque o ajuste é pequeno, rápido e feito no próprio protótipo.', 'Nota cheia: explica que a correção é imediata com lápis e borracha e que dispensa reunião formal pela agilidade. Metade: diz que não precisa de reunião, sem explicar a agilidade. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 16, 3, 'Explique por que o segundo testador deve receber a versão corrigida logo em seguida.', 0.4, 'O segundo testador deve receber a versão corrigida logo em seguida para testar o ajuste sem perder o ritmo e confirmar se a correção funcionou.', 'Nota cheia: explica que a versão corrigida deve ir logo ao segundo testador, para validar o ajuste enquanto o ciclo está ativo. Metade: diz que ele deve receber a versão corrigida, sem o motivo. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 17, 1, 'Descreva o primeiro passo do ciclo e o que é produzido nele.', 0.2, 'O passo 1 é o desenho inicial da tela no papel, que é o que será testado.', 'Nota cheia: indica o desenho inicial da tela no papel como primeiro passo e o que é produzido. Metade: indica o desenho, sem a tela no papel. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 17, 2, 'Descreva o segundo e o terceiro passos, com o que acontece com as dúvidas e os travamentos.', 0.4, 'O passo 2 é aplicar o teste com um colega. O passo 3 é anotar as dúvidas e os travamentos observados durante o teste.', 'Nota cheia: descreve o teste com o colega (passo 2) e a anotação das dúvidas e travamentos (passo 3). Metade: descreve só um dos dois passos. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 17, 3, 'Descreva o quarto passo e explique por que ele deve ser seguido de um novo teste imediato.', 0.4, 'O passo 4 é ajustar a lápis. Deve ser seguido de um novo teste imediato, porque só o teste mostra se o ajuste resolveu o problema.', 'Nota cheia: descreve o ajuste a lápis e explica que o novo teste imediato confirma o ajuste. Metade: descreve o ajuste, sem o novo teste ou sem o motivo. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 18, 1, 'Descreva o problema encontrado na versão 1 da tela.', 0.2, 'Na versão 1, a tela tinha uma lista enorme com 30 horários misturados, sem divisão de dias ou filtros de turno. O usuário passou 45 segundos rolando e desistiu.', 'Nota cheia: descreve a lista longa de horários misturados, sem divisão ou filtros, e o usuário rolando e desistindo. Metade: descreve só a lista ou só a desistência. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 18, 2, 'Descreva a mudança feita a lápis na versão 2 e o que ela organiza.', 0.4, 'Na versão 2, a equipe recortou um calendário visual no topo e três blocos de botões (Manhã, Tarde e Noite), o que organiza os horários por data e por turno.', 'Nota cheia: descreve o calendário no topo e os blocos Manhã, Tarde e Noite, e explica que organizam os horários. Metade: descreve a mudança, sem os blocos ou sem a organização. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 18, 3, 'Explique a diferença de desempenho observada no reteste e o que ela comprova sobre o ajuste.', 0.4, 'No reteste, o segundo usuário concluiu o agendamento em 8 segundos, contra os 45 segundos da versão 1. Isso comprova que a organização por calendário e turnos reduziu a busca e que o ajuste funcionou.', 'Nota cheia: compara o tempo do reteste (8 segundos) com o da versão 1 (45 segundos) e conclui que o ajuste funcionou. Metade: cita a melhora, sem os tempos ou sem a conclusão. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 19, 1, 'Descreva o diagnóstico do problema encontrado no teste.', 0.2, 'O usuário escolheu a data da consulta, mas não sabia se o sistema gravou a escolha. O diagnóstico é a falta de feedback visual de confirmação na tela.', 'Nota cheia: descreve a dúvida sobre a gravação da data e identifica a falta de feedback visual de confirmação. Metade: descreve a dúvida do usuário, sem o diagnóstico de feedback. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 19, 2, 'Descreva a ação física feita no protótipo para resolver o problema.', 0.4, 'A ação física foi desenhar uma nota adesiva com aviso de sucesso e colá-la no protótipo, para confirmar a escolha na tela.', 'Nota cheia: descreve a nota adesiva com aviso de sucesso colada no protótipo. Metade: descreve um aviso de confirmação, sem a nota adesiva. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 19, 3, 'Explique o que o reteste precisa confirmar para dar o ajuste como validado.', 0.4, 'O reteste precisa confirmar que o usuário percebe a confirmação sem ajuda. No caso da aula, o usuário seguinte confirmou o entendimento em 2 segundos.', 'Nota cheia: explica que o reteste confirma que o usuário percebe o aviso sem ajuda (pode citar os 2 segundos). Metade: diz que o reteste verifica o ajuste, sem o critério de percepção. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 20, 1, 'Descreva o problema que o teste revelou e o que ele indica sobre a tela.', 0.2, 'O teste revelou que quatro de cinco testadores tocaram no logotipo achando que era o botão de voltar. Isso indica que a tela não tem o botão de voltar visível, ou seja, falta o elemento que o usuário espera.', 'Nota cheia: descreve os quatro testadores que tocaram no logotipo achando ser o botão de voltar e indica a ausência do elemento esperado. Metade: descreve o erro dos testadores, sem indicar a ausência do elemento. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 20, 2, 'Descreva a alteração a lápis que você faria imediatamente.', 0.4, 'A alteração a lápis imediata é desenhar um botão de voltar visível no topo da tela.', 'Nota cheia: propõe desenhar um botão de voltar visível, no topo da tela. Metade: propõe um botão de voltar, sem a visibilidade ou o lugar. Zero: em branco, errado (ex.: mudar o logotipo sem justificar) ou fora do tema.'),
      (v_atividade, 20, 3, 'Explique por que essa alteração resolve o diagnóstico, relacionando-a ao elemento esperado pelo usuário.', 0.4, 'A alteração resolve o diagnóstico porque coloca o elemento que o usuário espera (o botão de voltar) de forma clara, no lugar onde ele procura, e deixa de confundir com o logotipo.', 'Nota cheia: relaciona o botão de voltar visível ao elemento esperado pelo usuário e explica que resolve a confusão com o logotipo. Metade: diz que o botão resolve, sem relacionar com o elemento esperado. Zero: em branco, errado ou fora do tema.');
end $$;
